import React, { Component } from 'react';

import { BlockSpoilerComponent } from '../block-spoiler-component.js';

type Props = {
  blockProps?: $TSFixMe;
  componentData?: $TSFixMe;
  pluginType?: string;
  onClick?: (...args: $TSFixMe[]) => void;
  className?: string;
  setFocusToBlock?: (...args: $TSFixMe[]) => void;
  setInPluginEditingMode?: (...args: $TSFixMe[]) => void;
  store?: $TSFixMe;
  block?: $TSFixMe;
  t: (key: string) => string;
  isMobile?: boolean;
};

export const SpoilerEditorWrapper = (config: $TSFixMe) => (WrappedComponent: $TSFixMe) => {
  return class spoilerWrapper extends Component<Props> {
    static alignmentClassName = WrappedComponent?.alignmentClassName;

    static sizeClassName = WrappedComponent?.sizeClassName;

    static textWrapClassName = WrappedComponent?.textWrapClassName;

    static customClassName = WrappedComponent?.customClassName;

    constructor(props: Props) {
      super(props);
      const type = props.blockProps.type?.replace('wix-draft-plugin-', '');
      // @ts-expect-error
      this.pluginType = type[0].toUpperCase() + type.slice(1);
    }

    handleDescriptionChange = (description: string) => {
      this.updateComponentData({ description });
    };

    handleButtonContentChange = (buttonContent: $TSFixMe) => {
      this.updateComponentData({ buttonContent });
    };

    updateComponentData = (data: $TSFixMe) => {
      const { componentData } = this.props;
      const { spoiler } = componentData?.config ?? {};
      const config = { ...componentData?.config, spoiler: { ...spoiler, ...data } };
      this.props.store.update(
        'componentData',
        { ...componentData, config },
        this.props.block.getKey()
      );
    };

    render() {
      const { componentData, onClick, className, setInPluginEditingMode, blockProps, isMobile, t } =
        this.props;
      const hasSpoiler = this.props.componentData?.config?.spoiler?.enabled || false;

      return hasSpoiler ? (
        <BlockSpoilerComponent
          disabledRevealSpoilerBtn
          isEditableText
          handleButtonContentChange={this.handleButtonContentChange}
          handleDescriptionChange={this.handleDescriptionChange}
          // @ts-expect-error
          pluginType={this.pluginType}
          componentData={componentData}
          onClick={onClick}
          className={className}
          setFocusToBlock={blockProps?.setFocusToBlock}
          setInPluginEditingMode={setInPluginEditingMode}
          isMobile={isMobile}
          t={t}
          {...config}
        >
          <WrappedComponent {...this.props} />
        </BlockSpoilerComponent>
      ) : (
        <WrappedComponent {...this.props} />
      );
    }
  };
};
